const fs = require('fs-extra');
const path = require('path');
const appRoot = require("app-root-path")

const outputFileName = "EventsHelper.lua"

function buildEventName(systemName, eventId) {
    return `${systemName}://${eventId}`
}


function _buildEventFireStr(eventConfig, isSub = false) {
    var name = eventConfig.EventName
    var systemName = eventConfig.SystemName
    var str = ""
    var prefix = isSub ? "    " : ""
    var modulePrefix = isSub ? "" : "module."
    var commaStr = isSub ? "," : ""

    if (eventConfig.Description) {
        str += `${prefix}-- ${eventConfig.Description} \n`;
    }
    var eventName = buildEventName(systemName, name)
    var type = eventConfig.Type ?? "Fire"

    if (eventConfig.Parameters) {
        let paramList = Object.keys(eventConfig.Parameters).join(', ');
        str += `${prefix}${modulePrefix}${name}_${type} = function(${paramList})\n`
        str += `${prefix}    local channel = EventBus.GetChannel("${eventName}")\n`
        str += `${prefix}    return channel.${[type]} (${paramList}) \n`
    } else {
        str += `${prefix}${modulePrefix}${name}_${type} = function() \n`
        str += `${prefix}    local channel = EventBus.GetChannel("${eventName}")\n`
        str += `${prefix}    return channel.${[type]} () \n`
    }
    str += `${prefix}end${commaStr} \n\n`
    return str
}



function _buildEventConnectStrLegacy(eventConfig, isSub = false) {

    var name = eventConfig.EventName
    var systemName = eventConfig.SystemName
    var str = ""
    var prefix = isSub ? "    " : ""
    var modulePrefix = isSub ? "" : "module."
    var commaStr = isSub ? "," : ""


    var eventName = buildEventName(systemName, name)

    var type = "Connect"
    if (eventConfig.Type == "FireAllClients" || eventConfig.Type == "FireClient") {
        type = "ConnectS2C"
    } else if (eventConfig.Type == "FireServer") {
        type = "ConnectC2S"
    } else if (eventConfig.Type == "Invoke") {
        type = "OnInvoke"
    } else if (eventConfig.Type == "InvokeServer") {
        type = "OnInvokeC2S"
    }

    var params = {}

    if (eventConfig.Parameters) {
        // 将对象的每个成员复制到 params
        // Merge eventConfig.Parameters into params
        for (const [key, value] of Object.entries(eventConfig.Parameters)) {
            params[key] = "any";
        }
    }


    let paramList = Object.keys(params).map(x => x + `: ${params[x]}`).join(', ');

    // --- gen func
    str += `${prefix}${modulePrefix}${name}_${type} = function(handler: (${paramList}) -> ()) \n`
    if (eventConfig.ScriptConnect) {
        var scriptConnect = eventConfig.ScriptConnect.split('\n').map(x => prefix + "    " + x).join('\n')
        str += `${scriptConnect} \n\n`
    }

    var tail = ""

    // channel
    str += `${prefix}    local channel = EventBus.GetChannel("${eventName}") \n`

    // return
    str += `${prefix}    return channel.${type} ( handler${tail}) \n`


    str += `${prefix}end${commaStr} \n\n`

    return str
}


function _buildEventConnectStr(eventConfig, isSub = false) {

    var name = eventConfig.EventName
    var systemName = eventConfig.SystemName
    var str = ""
    var prefix = isSub ? "    " : ""
    var modulePrefix = isSub ? "" : "module."
    var commaStr = isSub ? "," : ""


    var eventName = buildEventName(systemName, name)

    var type = "Connect"
    if (eventConfig.Type == "FireAllClients" || eventConfig.Type == "FireClient") {
        type = "ConnectS2C"
    } else if (eventConfig.Type == "FireServer") {
        type = "ConnectC2S"
    } else if (eventConfig.Type == "Invoke") {
        type = "OnInvoke"
    } else if (eventConfig.Type == "InvokeServer") {
        type = "OnInvokeC2S"
    }

    var params = {}

    if (eventConfig.Parameters) {
        // 将对象的每个成员复制到 params
        // Merge eventConfig.Parameters into params
        for (const [key, value] of Object.entries(eventConfig.Parameters)) {
            var splits = value.split(",")
            params[key] = {
                type: splits[0].trim(),
                comment: splits[1]
            };
        }
    }

    var keys = Object.keys(params)

    var isPlayerScope = keys[0] == "player"

    let paramList = keys.map(x => x + `: ${params[x].type}`).join(', ');

    if (paramList != "") {
        paramList += ","
    }
    paramList += "ts:TangSengFacade"

    // --- gen func
    str += `${prefix}${modulePrefix}${name}_${type} = function(handler: (${paramList}) -> ()) \n`
    if (eventConfig.ScriptConnect) {
        var scriptConnect = eventConfig.ScriptConnect.split('\n').map(x => prefix + "    " + x).join('\n')
        str += `${scriptConnect} \n\n`
    }


    if (isPlayerScope) {
        str += `${prefix}    handler = TangSeng.InjectionWrap(handler, ${keys.length}, true) \n`
    } else {
        str += `${prefix}    handler = TangSeng.InjectionWrap(handler, ${keys.length}) \n`
    }

    var tail = ""


    // channel
    str += `${prefix}    local channel = EventBus.GetChannel("${eventName}") \n`

    // return
    str += `${prefix}    return channel.${type} ( handler${tail}) \n`


    str += `${prefix}end${commaStr} \n\n`

    return str
}

function generateEventsHelper(events) {

    // group events by FolderPath
    // 按FolderPath对事件进行分组
    const groupedEvents = events.reduce((acc, event) => {
        const folderPath = event.FolderPath || 'Default';
        if (!acc[folderPath]) {
            acc[folderPath] = [];
        }
        acc[folderPath].push(event);
        return acc;
    }, {});

    // 为每个分组生成事件辅助函数
    Object.entries(groupedEvents).forEach(([folderPath, groupEvents]) => {
        let helper = "";
        helper += "----------自动生成----------\n\n";
        helper += "local EventBus = require(game.ReplicatedStorage.Packages.EventBus)\n\n";
        helper += "local TangSeng = require(game.ReplicatedStorage.Packages.TangSeng)\n\n";
        helper += "local module = {}\n\n";

        groupEvents.forEach(eventConfig => {
            const eventName = eventConfig.EventName;
            if (eventName !== "FilePath") {
                helper += _buildEventConnectStr(eventConfig)
                helper += _buildEventFireStr(eventConfig)
            }
        });

        helper += "return module\n";

        // 写入文件
        const outputPath = path.join(folderPath, 'EventsHelper.lua');
        fs.writeFileSync(outputPath, helper);
        console.log(`write file ${outputPath}`)
    });


}



function generateAllEventsHelpers(events, outputFolder) {
    var helper = ""
    helper += `---------- auto generated by TangSeng ----------\n\n`;
    helper += `local EventBus = require(game.ReplicatedStorage.Packages.EventBus)\n\n`
    helper += "local TangSeng = require(game.ReplicatedStorage.Packages.TangSeng)\n\n";
    helper += `local module = {}\n\n`


    // group events by FolderPath
    // 按FolderPath对事件进行分组
    const groupedEvents = events.reduce((acc, event) => {
        const folderPath = event.SystemName || 'Default';
        if (!acc[folderPath]) {
            acc[folderPath] = [];
        }
        acc[folderPath].push(event);
        return acc;
    }, {});


    Object.entries(groupedEvents).forEach(([systemName, groupEvents]) => {
        helper += `module.${systemName} = {\n`
        groupEvents.forEach((value) => {

            if (!value.Public || value.Public < 1) {
                return
            }

            var key = value.EventName

            if (key == "FilePath") {
                return
            }

            helper += _buildEventFireStr(value, true)

            if (value.LegacyConnect) {
                helper += _buildEventConnectStrLegacy(value, true)
            } else {
                helper += _buildEventConnectStr(value, true)
            }


        })
        // 去除最后一个换行
        helper = helper.slice(0, -1)
        helper += `}\n\n`
    })
    helper += `return module\n`
    const sPath = path.join(appRoot.path, outputFolder, outputFileName);
    fs.writeFileSync(sPath, helper);
}



function gen(config, outputPath) {
    generateEventsHelper(config)
    generateAllEventsHelpers(config, outputPath)
}


module.exports = gen;